-- Luma TV 2.0 installer. Usage in OpenOS: wget -f <url> /tmp/luma.lua && /tmp/luma.lua
local fs=require('filesystem')
local function b64(s)
 local B='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
 s=s:gsub('[^%w+/=]','')
 local acc={};local buf=0;local n=0
 for i=1,#s do
  local c=s:sub(i,i)
  if c~='=' then
   buf=(buf<<6)|(B:find(c,1,true)-1);n=n+6
   if n>=8 then n=n-8;acc[#acc+1]=string.char((buf>>n)&0xFF) end
  end
 end
 return table.concat(acc)
end
local function put(path,data)
 fs.makeDirectory(fs.path(path))
 local f=assert(io.open(path,'wb'));f:write(data);f:close()
 print(' + '..path)
end
