put([[/usr/bin/tv-demo.lua]],[[-- The entire demo is generated by Lua in the OC computer, with no external encoder.
local fs=require('filesystem');local root='/home/lumatv/media';fs.makeDirectory(root)
local force=({...})[1]=='--force'
local path=root..'/01-orbit.ltv'
if force or not fs.exists(path) then
 local f=assert(io.open(path,'wb'));local w,h,frames=64,32,36
 assert(f:write('LTV1\n'..w..' '..h..' 6 '..frames..'\n'))
 for frame=0,frames-1 do
  local lines={}
  local angle=frame*2*math.pi/frames;local ox=32+math.sin(angle)*18;local oy=16+math.cos(angle)*10
  for y=0,h-1 do local row={}
   for x=0,w-1 do
    local dx,dy=x-32,y-16;local d=math.sqrt(dx*dx+dy*dy)
    local index=0
    if d>12.5 and d<14 then index=2 end
    if ((x*31+y*17)%137)==0 then index=14 end
    if d<7 then index=x<30 and 3 or 4 end
    if (x-ox)^2+(y-oy)^2<9 then index=13 end
    row[#row+1]=string.char(index)
   end;lines[#lines+1]=table.concat(row)
  end
  assert(f:write(table.concat(lines)));if os.sleep then os.sleep(0) end
 end
 assert(f:close());print('Создано '..path)
else print('Демо уже есть: '..path) end
local bmp=root..'/02-landscape.bmp'
if force or not fs.exists(bmp) then
 local w,h=96,48;local stride=math.floor((w*3+3)/4)*4
 local f=assert(io.open(bmp,'wb'));assert(f:write('BM'..string.pack('<I4I2I2I4',54+stride*h,0,0,54)..string.pack('<I4i4i4I2I2I4I4i4i4I4I4',40,w,h,1,24,0,stride*h,2835,2835,0,0)))
 for y=h-1,0,-1 do local row={}
  for x=0,w-1 do
   local r,g,b=25+math.floor(y/3),42+math.floor(y/2),64+math.floor(y/2)
   if (x-73)^2+(y-12)^2<49 then r,g,b=243,205,120 end
