   if y>35+math.sin(x/22)*5 then r,g,b=41,70,84 end
   row[#row+1]=string.char(b,g,r)
  end
  assert(f:write(table.concat(row)..string.rep('\0',stride-w*3)))
 end;assert(f:close());print('Создано '..bmp)
end
