 end
 -- Segment-aware word wrap: link words keep their link id and screen position.
 local function layout(width)
  local out={}
  for para in (self.text..'\n'):gmatch('(.-)\n') do
   local segs={};local i=1
   while true do
    local s,e=para:find('\1(%d+)\2',i)
    if not s then if i<=#para then segs[#segs+1]={s=para:sub(i)} end break end
    if s>i then segs[#segs+1]={s=para:sub(i,s-1)} end
