   end
   local line={};local len=0
   for _,seg in ipairs(segs) do
    for word in seg.s:gmatch('%S+') do
     local wl=U.len(word)
     if wl>width then
      if len>0 then out[#out+1]=line;line={};len=0 end
      while U.len(word)>width do out[#out+1]={{s=U.sub(word,1,width),link=seg.link}};word=U.sub(word,width+1) end
     end
     if len>0 and len+1+U.len(word)>width then out[#out+1]=line;line={};len=0 end
     line[#line+1]={s=word,link=seg.link};len=len+U.len(word)+1
    end
   end
   out[#out+1]=line
  end
