  ui:button('web-url',x,y,aw,ui:clip(self.url,aw-4),function()
   ctx.prompt('Адрес страницы',self.url=='luma:home' and 'https://' or self.url,function(s) if s and s~='' then navigate(s,true) end end)
  end)
  ui:button('web-open',x+aw+2,y,12,'Открыть',function() navigate(self.url,true) end)
