put([[/usr/lib/lumatv/boot.lua]],[[-- Power-on splash: pixel logo, staged progress bar, any key skips. Pure GPU cells.
local computer=require('computer')
local event=require('event')
local logo=require('lumatv.logo')
local M={}
function M.show(ui,config)
 local w,h=ui.w,ui.h
 local scale=(w>=110 and h>=34) and 2 or 1
 local text='LUMA TV'
 local lw=logo.width(text,scale);local lh=logo.height(scale)
 local lx=math.max(1,math.floor((w-lw)/2)+1);local ly=math.max(1,math.floor(h*0.3)-lh)
 local barW=math.min(w-16,54);local bx=math.floor((w-barW)/2)+1;local by=math.min(h-7,ly+lh+4)
 local stages={'Подготовка экрана','Проверка памяти','Загрузка модулей','Запуск рабочего стола'}
 local dur=2.4
 local t0=computer.uptime();local last=-1;local skipped=false
 while true do
  local p=config.motion and (computer.uptime()-t0)/dur or 1;if p>1 then p=1 end
  local frame=math.floor(p*100)
  if frame~=last then
   last=frame
   ui:begin()
   logo.draw(ui,lx,ly,text,scale,ui.c.bg,function(ch) return logo.color(ch,ui.c.accent) end)
   local tag='ДОМАШНИЙ ЭКРАН'
   ui:text(math.max(1,math.floor((w-#tag)/2)+1),ly+lh+1,tag,ui.c.muted,ui.c.bg,#tag)
   ui:rect(bx,by,barW,2,ui.c.panel)
   local fill=math.floor(barW*p+0.5)
   if fill>0 then ui:rect(bx,by,fill,2,ui.c.accent) end
   local st=stages[math.min(#stages,math.floor(p*#stages)+1)]
   ui:text(math.max(1,math.floor((w-#st)/2)+1),by+3,st,ui.c.text,ui.c.bg,#st)
   local hint=config.motion and 'Нажмите любую клавишу, чтобы пропустить' or ''
   ui:text(math.max(1,math.floor((w-#hint)/2)+1),h-2,hint,ui.c.muted,ui.c.bg,#hint)
   ui:flush()
  end
  if p>=1 then break end
  local e={event.pull(0.05)}
  if e[1]=='key_down' or e[1]=='touch' or e[1]=='interrupted' then skipped=true;break end
  if not config.motion then break end
 end
 if not skipped and os.sleep then os.sleep(config.motion and 0.25 or 0.4) end
end
return M
]])
put([[/usr/lib/lumatv/codec.lua]],[[local M={palette={0x0D131E,0x172231,0x294654,0x428995,0x8EDBD3,0xE5ECF6,0x4D80CD,0x8ABAF0,0x66B09F,0xB6E8D8,0x9D88C5,0xD0C5E8,0xC28E3F,0xF3CD78,0x8195AE,0xF4A99C}}
local function open(path) local f,e=io.open(path,'rb');if not f then error(e,0) end;return f end
function M.ltv(path)
 local f=open(path)
 local ok,result=pcall(function()
  assert(f:read('*l')=='LTV1','Не LTV1')
  local hdr=f:read('*l') or '';local w,h,fps,count=hdr:match('^(%d+) (%d+) ([%d.]+) (%d+)$')
  w=tonumber(w);h=tonumber(h);fps=tonumber(fps);count=tonumber(count)
  assert(w and h and fps and count and w>=1 and w<=160 and h>=1 and h<=100 and fps>0 and fps<=20 and count>=1 and count<=10000,'Некорректный заголовок LTV')
  local offset=f:seek();local size=f:seek('end');assert(size==offset+w*h*count,'Неверный размер LTV');f:seek('set',offset)
  local obj={w=w,h=h,fps=fps,count=count}
  function obj.frame(index)
   assert(index>=1 and index<=count,'Кадр вне диапазона');assert(f:seek('set',offset+(index-1)*w*h))
   local s=f:read(w*h);assert(s and #s==w*h,'Кадр обрезан')
   local pixels={};for i=1,#s do local n=s:byte(i);assert(n<16,'Неизвестный цвет');pixels[i]=M.palette[n+1] end
   return {w=w,h=h,pixels=pixels}
