 local ok,result=pcall(function()
  local head=f:read(54);assert(head and #head==54 and head:sub(1,2)=='BM','Не BMP')
  local off=string.unpack('<I4',head,11);local dib=string.unpack('<I4',head,15)
  local w,h=string.unpack('<i4i4',head,19);local planes,bits=string.unpack('<I2I2',head,27);local compression=string.unpack('<I4',head,31)
