end
function M.close(t) if t and t.h then pcall(t.h.close);t.h=nil end end
function M.poll(t)
 if not t.h then return nil,'Запрос закрыт' end
 local function fail(e) M.close(t);return nil,tostring(e) end
 if computer.uptime()-t.started>25 then return fail('Таймаут 25 с') end
 if not t.connected then
  local ok,r,e=pcall(t.h.finishConnect)
  if not ok or (r==nil and e) then return fail(e or r) end
  if not r then return false end
  t.connected=true
