  local f,e=io.open(tmp,'wb'); if not f then return nil,e end
  local ok,err=f:write(data); local closed,ce=f:close()
  if not ok or closed==nil then fs.remove(tmp); return nil,err or ce end
  local had=fs.exists(path)
  if had then
    if fs.exists(bak) then local r,re=fs.remove(bak); if not r then fs.remove(tmp);return nil,re end end
    local r,re=fs.rename(path,bak); if not r then fs.remove(tmp);return nil,re end
  end
  local r,re=fs.rename(tmp,path)
  if not r then if had then fs.rename(bak,path) end;fs.remove(tmp);return nil,re end
  return true
end
function M.lines(text)
